vec2 randomPoint(float seed) {
    return vec2(fract(sin(seed * 1234.5678) * 43758.5453),
        fract(cos(seed * 987.5432) * 12345.6789));
}
vec3 regionColor(int regionIndex) {
    // Define unique colors for each region
    if (regionIndex == 0) return vec3(1.0, 0.0, 0.0); // Red
    if (regionIndex == 1) return vec3(0.0, 1.0, 0.0); // Green
    if (regionIndex == 2) return vec3(0.0, 0.0, 1.0); // Blue
    if (regionIndex == 3) return vec3(1.0, 1.0, 0.0); // Yellow
    if (regionIndex == 4) return vec3(1.0, 0.0, 1.0); // Magenta
    if (regionIndex == 5) return vec3(0.0, 1.0, 1.0); // Cyan
    if (regionIndex == 6) return vec3(1.0, 0.5, 0.0); // Orange
    return vec3(0.5, 0.5, 0.5); // Default gray
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = (fragCoord) / iResolution.xy;
    uv.x *= (iResolution.x) / iResolution.y;

    float min_distance = 1.0;

    vec3 color;

    vec2 points[8];
    points[0] = randomPoint(1.30);
    points[1] = randomPoint(2.03);
    points[2] = randomPoint(3.30);
    points[3] = randomPoint(4.30);
    points[4] = randomPoint(5.30);
    points[5] = randomPoint(6.0);
    points[6] = (iMouse.xy) / iResolution.y; // Interactive point
    points[7] = randomPoint(8.0);

    int idx = -1;
    for (int i = 0; i < 8; i++)
    {
        float dist = distance(uv, points[i]);

        if (dist < min_distance)
        {
            min_distance = dist;
            idx = i;
        }

        color = vec3(regionColor(idx))*vec3(1.0-min_distance);

        fragColor = vec4(color, 1.0);
    }
}
